template <bool B>
inline bool VerifyPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyPayload(
        verifier,  values->Get(i), types->GetEnum<Payload>(i))) {
      return false;
    }
  }
  return true;
}

inline const camera::v1::Envelope *GetEnvelope(const void *buf) {
  return ::flatbuffers::GetRoot<camera::v1::Envelope>(buf);
}

inline const camera::v1::Envelope *GetSizePrefixedEnvelope(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<camera::v1::Envelope>(buf);
}

inline const char *EnvelopeIdentifier() {
  return "CAM1";
}

inline bool EnvelopeBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, EnvelopeIdentifier());
}

inline bool SizePrefixedEnvelopeBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, EnvelopeIdentifier(), true);
}

template <bool B = false>
inline bool VerifyEnvelopeBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<camera::v1::Envelope>(EnvelopeIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedEnvelopeBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<camera::v1::Envelope>(EnvelopeIdentifier());
}

inline void FinishEnvelopeBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<camera::v1::Envelope> root) {
  fbb.Finish(root, EnvelopeIdentifier());
}

inline void FinishSizePrefixedEnvelopeBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<camera::v1::Envelope> root) {
  fbb.FinishSizePrefixed(root, EnvelopeIdentifier());
}

